using UmatiGateway.Model;

namespace UmatiGateway.Mapping;

/// <summary>
/// Derives the data model's Production.ProgramExecution snapshot and its events
/// (Started / Interrupted / Resumed / Ended / Aborted) from the state of the active program.
/// The OPC UA source only offers the current state; ExecutionId, StartTime and the lifecycle
/// events are generated by the gateway.
/// </summary>
public sealed class ProgramExecutionTracker
{
    public sealed record Counters(double? EnergyElectricity = null, double? EnergyCompressedAir = null);

    public sealed record Input(string? State, string? Program, string? JobOrderId = null, Counters? Counters = null);

    public sealed record Snapshot(Dictionary<string, object?>? Value, DateTime Timestamp, string? CorrelationId);

    public sealed record Result(Snapshot? Snapshot, List<DataEvent> Events);

    private sealed class Active
    {
        public string Id = "";
        public DateTime StartTime;
        public string State = "";
        public string? Program;
        public string? JobOrderId;
        public Counters Start = new();
    }

    private readonly Func<string> _newId;
    private Active? _active;
    private bool _baselineDone;
    private string? _lastState;

    public ProgramExecutionTracker(Func<string>? newId = null) => _newId = newId ?? (() => Guid.NewGuid().ToString());

    public string? CurrentExecutionId =>
        _active is { State: "Running" or "Interrupted" } ? _active.Id : null;

    private static Dictionary<string, object?> ValueOf(Active a, string state)
    {
        var v = new Dictionary<string, object?>
        {
            ["ExecutionId"] = a.Id,
            ["State"] = state,
            ["StartTime"] = Envelope.Iso(a.StartTime),
        };
        if (!string.IsNullOrEmpty(a.JobOrderId)) v["JobOrderID"] = a.JobOrderId;
        if (!string.IsNullOrEmpty(a.Program)) v["ActiveProgram"] = a.Program;
        return v;
    }

    private static Snapshot Snap(Active a, string state, DateTime ts) => new(ValueOf(a, state), ts, a.Id);

    private static DataEvent Ev(string name, DateTime ts, Dictionary<string, object?> v) =>
        new() { Event = name, Timestamp = Envelope.Iso(ts), Value = v };

    public Result Update(Input input, DateTime now)
    {
        var events = new List<DataEvent>();
        var state = input.State;

        // first observation: adopt a running execution silently (no event for the past)
        if (!_baselineDone)
        {
            _baselineDone = true;
            _lastState = state;
            if (state is "Running" or "Interrupted")
            {
                _active = new Active { Id = _newId(), StartTime = now, State = state, Program = input.Program, JobOrderId = input.JobOrderId, Start = input.Counters ?? new() };
                return new Result(Snap(_active, state, now), events);
            }
            return new Result(new Snapshot(null, now, null), events);
        }

        if (state is null || state == _lastState) return new Result(null, events);
        _lastState = state;
        var cur = _active;
        var live = cur is { State: "Running" or "Interrupted" };

        if (state == "Running")
        {
            if (live && cur!.State == "Interrupted")
            {
                cur.State = "Running";
                events.Add(Ev("Production.ProgramExecutionResumed", now, ValueOf(cur, "Running")));
                return new Result(Snap(cur, "Running", now), events);
            }
            if (!live)
            {
                var a = new Active { Id = _newId(), StartTime = now, State = "Running", Program = input.Program, JobOrderId = input.JobOrderId, Start = input.Counters ?? new() };
                _active = a;
                events.Add(Ev("Production.ProgramExecutionStarted", now, ValueOf(a, "Running")));
                return new Result(Snap(a, "Running", now), events);
            }
            return new Result(null, events);
        }

        if (state == "Interrupted")
        {
            if (live && cur!.State == "Running")
            {
                cur.State = "Interrupted";
                events.Add(Ev("Production.ProgramExecutionInterrupted", now, ValueOf(cur, "Interrupted")));
                return new Result(Snap(cur, "Interrupted", now), events);
            }
            return new Result(null, events);
        }

        // Ended / Aborted
        if (live)
        {
            var a = cur!;
            if (!string.IsNullOrEmpty(input.Program)) a.Program = input.Program;
            var v = ValueOf(a, state);
            v["Duration"] = Transforms.Clean((now - a.StartTime).TotalSeconds);
            AddDelta(v, "EnergyElectricity", a.Start.EnergyElectricity, input.Counters?.EnergyElectricity);
            AddDelta(v, "EnergyCompressedAir", a.Start.EnergyCompressedAir, input.Counters?.EnergyCompressedAir);
            a.State = state;
            events.Add(Ev(state == "Ended" ? "Production.ProgramExecutionEnded" : "Production.ProgramExecutionAborted", now, v));
            return new Result(Snap(a, state, now), events);
        }
        return new Result(null, events);
    }

    private static void AddDelta(Dictionary<string, object?> v, string key, double? start, double? end)
    {
        if (start is { } s && end is { } e && e >= s) v[key] = Transforms.Clean(e - s);
    }
}
